import{_ as m,C as h,o,c as p,a9 as r,b as i,w as t,a as s,E as a,a8 as d,j as l}from"./chunks/framework.BOiBTRPC.js";const E=JSON.parse('{"title":"Windows, Watermarks & Late Data","description":"Event time vs processing time, window types, watermark mechanics, and the design decisions that determine when results are correct enough.","frontmatter":{"title":"Windows, Watermarks & Late Data","description":"Event time vs processing time, window types, watermark mechanics, and the design decisions that determine when results are correct enough."},"headers":[],"relativePath":"streaming/windows-watermarks.md","filePath":"streaming/windows-watermarks.md"}'),g={name:"streaming/windows-watermarks.md"};function w(b,e,f,k,v,y){const n=h("Mermaid"),u=h("WindowViz"),c=h("QuizCard");return o(),p("div",null,[e[8]||(e[8]=r('<h1 id="windows-watermarks-late-data" tabindex="-1">Windows, Watermarks &amp; Late Data <a class="header-anchor" href="#windows-watermarks-late-data" aria-label="Permalink to &quot;Windows, Watermarks &amp; Late Data&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Unbounded data has no &quot;end of file,&quot; so the central question of streaming is <em>when is a result final?</em> Watermarks are the bet your system makes on completeness; windows are where that bet gets paid out. Get the trade-offs wrong and you either report wrong numbers silently or hold state forever.</p></blockquote><h2 id="three-clocks-one-problem" tabindex="-1">Three clocks, one problem <a class="header-anchor" href="#three-clocks-one-problem" aria-label="Permalink to &quot;Three clocks, one problem&quot;">​</a></h2><p>Every event can be timed three ways:</p><ul><li><strong>Event time</strong> — when the thing happened (device clock, <code>created_at</code>). The only time that makes results reproducible across replays and lag.</li><li><strong>Ingestion time</strong> — when the event entered the system (Kafka log append). A cheap approximation; monotonic, but it moves with pipeline speed, not reality.</li><li><strong>Processing time</strong> — wall-clock when the engine sees the event. Simplest, and wrong for any result that must survive a backfill or a consumer outage.</li></ul><p>The gap between event time and processing time — <strong>skew</strong> — is where all the difficulty lives:</p>',6)),(o(),i(d,null,{default:t(()=>[a(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20device%5B%22Device%20%2F%20source%22%5D%0A%20%20%20%20%20%20%20%20E1%5B%22e1%20%40%2010%3A00%22%5D%0A%20%20%20%20%20%20%20%20E2%5B%22e2%20%40%2010%3A02%22%5D%0A%20%20%20%20%20%20%20%20E3%5B%22e3%20%40%2010%3A05%3Cbr%2F%3Eoffline%20mobile%20%E2%80%94%3Cbr%2F%3Ebatches%20late%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20pipe%5B%22Pipeline%22%5D%0A%20%20%20%20%20%20%20%20K%5B%22Kafka%22%5D%0A%20%20%20%20%20%20%20%20FL%5B%22Stream%20processor%22%5D%0A%20%20%20%20end%0A%20%20%20%20E1%20--%3E%7C%22arrives%2010%3A00%3A05%22%7C%20K%0A%20%20%20%20E2%20--%3E%7C%22arrives%2010%3A02%3A03%22%7C%20K%0A%20%20%20%20E3%20--%3E%7C%22arrives%2010%3A40%3A00%3Cbr%2F%3E%2B35%20min%20skew%22%7C%20K%0A%20%20%20%20K%20--%3E%20FL%0A%20%20%20%20subgraph%20clocks%5B%22Which%20clock%20decides%20the%20window%3F%22%5D%0A%20%20%20%20%20%20%20%20ET%5B%22Event%20time%20%E2%86%92%2010%3A05%20bucket%20%E2%9C%85%3Cbr%2F%3Ereproducible%2C%20but%20when%20do%20we%20close%20it%3F%22%5D%0A%20%20%20%20%20%20%20%20PT%5B%22Processing%20time%20%E2%86%92%2010%3A40%20bucket%3Cbr%2F%3E'correct'%20today%2C%20different%20on%20replay%22%5D%0A%20%20%20%20end%0A%20%20%20%20FL%20--%3E%20clocks%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"💡 Senior insight"),l("p",null,[s("Event time is the only honest answer, and it costs you a completeness problem: you can never "),l("em",null,"prove"),s(" no more 10:05 events are coming. Watermarks are the mechanism for betting on it — the entire chapter is how to size that bet.")])],-1)),e[10]||(e[10]=l("p",null,"The canonical mental picture is a scatter of events on event-time × processing-time axes: the ideal is the diagonal (event arrives the instant it happens); the watermark is a lagging curve underneath the leading edge of arrivals; the gap between curve and diagonal is the out-of-orderness bound you chose.",-1)),(o(),i(d,null,{default:t(()=>[a(n,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20skew%5B%22Event%20time%20(x)%20vs%20processing%20time%20(y)%22%5D%0A%20%20%20%20%20%20%20%20D%5B%22Diagonal%3A%20perfect%20world%3Cbr%2F%3Eevent_time%20%3D%20processing_time%22%5D%0A%20%20%20%20%20%20%20%20P%5B%22Points%3A%20actual%20arrivals%3Cbr%2F%3Escattered%20above%20the%20diagonal%22%5D%0A%20%20%20%20%20%20%20%20W%5B%22Watermark%20curve%3A%20lags%20the%3Cbr%2F%3Eleading%20edge%20by%20the%20bound%22%5D%0A%20%20%20%20end%0A%20%20%20%20D%20-.-%3E%7C%22reality%20is%20always%20above%22%7C%20P%0A%20%20%20%20P%20-.-%3E%7C%22WM%20guesses%20where%3Cbr%2F%3Ethe%20tail%20ended%22%7C%20W%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=r('<h2 id="the-four-questions-what-where-when-how" tabindex="-1">The four questions: What, Where, When, How <a class="header-anchor" href="#the-four-questions-what-where-when-how" aria-label="Permalink to &quot;The four questions: What, Where, When, How&quot;">​</a></h2><p>Streaming Systems (Akidau, Chernyak, Lax) frames every unbounded-data pipeline as answers to four questions. This chapter&#39;s sections map onto them — keep the table nearby as the organizing skeleton:</p><table tabindex="0"><thead><tr><th>Question</th><th>Answered by</th><th>Chapter section</th><th>The decision you&#39;re really making</th></tr></thead><tbody><tr><td><strong>What</strong> results are calculated?</td><td>Transformations: sums, joins, aggregations</td><td>(the business logic — out of scope here)</td><td>What the numbers mean</td></tr><tr><td><strong>Where</strong> in event time?</td><td>Event-time <strong>windowing</strong></td><td>Window types</td><td>Which events group into one result</td></tr><tr><td><strong>When</strong> in processing time are results materialized?</td><td><strong>Triggers</strong> + <strong>watermarks</strong></td><td>Watermarks; Firing</td><td>How long you wait before betting the input is complete</td></tr><tr><td><strong>How</strong> do refinements relate?</td><td><strong>Accumulation modes</strong></td><td>Firing: accumulation modes</td><td>Whether each output is a delta, a new value, or a correction</td></tr></tbody></table>',3)),(o(),i(d,null,{default:t(()=>[a(n,{id:"mermaid-126",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20WHAT%5B%22WHAT%20results%3F%3Cbr%2F%3Etransformations%3Cbr%2F%3E(Sum%2C%20Join%2C%20ML)%22%5D%20--%3E%20WHERE%5B%22WHERE%20in%20event%20time%3F%3Cbr%2F%3Ewindowing%22%5D%0A%20%20%20%20WHERE%20--%3E%20WHEN%5B%22WHEN%20in%20processing%20time%3F%3Cbr%2F%3Etriggers%20%2B%20watermarks%22%5D%0A%20%20%20%20WHEN%20--%3E%20HOW%5B%22HOW%20do%20refinements%20relate%3F%3Cbr%2F%3Eaccumulation%20modes%22%5D%0A%20%20%20%20subgraph%20stream%5B%22Streaming%20adds%20these%22%5D%0A%20%20%20%20%20%20%20%20WHEN%0A%20%20%20%20%20%20%20%20HOW%0A%20%20%20%20end%0A%20%20%20%20subgraph%20batch%5B%22Batch%20already%20had%20these%22%5D%0A%20%20%20%20%20%20%20%20WHAT%0A%20%20%20%20%20%20%20%20WHERE%0A%20%20%20%20end%0A%20%20%20%20WHEN%20-.-%3E%7C%22fires%20panes%20over%20time%22%7C%20NOTE%5B%22one%20window%20can%20emit%3Cbr%2F%3Emultiple%20outputs%20%E2%80%94%3Cbr%2F%3Ethe%20how%20question%20exists%3Cbr%2F%3Eonly%20because%20of%20when%22%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[s(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=r('<p>The payoff of the frame: <strong>batch is a degenerate case</strong> — one global window, one firing when input ends, one output. Everything else in this chapter is what falls out of un-baking those three assumptions.</p><h2 id="window-types" tabindex="-1">Window types <a class="header-anchor" href="#window-types" aria-label="Permalink to &quot;Window types&quot;">​</a></h2><p>Windows slice an unbounded stream into bounded chunks you can actually aggregate.</p><table tabindex="0"><thead><tr><th>Type</th><th>Definition</th><th>Events per window</th><th>Classic use</th></tr></thead><tbody><tr><td><strong>Tumbling (fixed)</strong></td><td>Adjacent, non-overlapping, size <em>s</em></td><td>exactly 1</td><td>&quot;events per minute/hour/day&quot;</td></tr><tr><td><strong>Sliding (hopping)</strong></td><td>Size <em>s</em>, slide <em>d</em> — overlapping when <em>d &lt; s</em></td><td>up to <em>s/d</em></td><td>&quot;rolling 10-min avg, computed every 2 min&quot;</td></tr><tr><td><strong>Session</strong></td><td>Gap <em>g</em> — closes after <em>g</em> inactivity; windows merge</td><td>variable</td><td>user sessions, clickstreams, device activity bursts</td></tr><tr><td><strong>Global</strong></td><td>One window for the whole key</td><td>all</td><td>only meaningful with triggers — &quot;emit every N events&quot;</td></tr><tr><td><strong>Count-based</strong></td><td>Every <em>n</em> records</td><td>—</td><td>processing-time fallbacks; avoid for analytics</td></tr></tbody></table>',4)),(o(),i(d,null,{default:t(()=>[a(n,{id:"mermaid-226",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20TUM%5B%22Tumbling%20%E2%80%94%20size%2010m%3A%20adjacent%2C%20non-overlapping%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20TW1%5B%22window%200-10%22%5D%20--%3E%20TW2%5B%22window%2010-20%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20SLI%5B%22Sliding%20%E2%80%94%20size%2010m%2C%20slide%205m%3A%20overlapping%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20SW1%5B%22window%200-10%22%5D%20--%3E%20SW2%5B%22window%205-15%22%5D%20--%3E%20SW3%5B%22window%2010-20%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20SES%5B%22Session%20%E2%80%94%20gap%205m%3A%20bursts%20group%2C%205m%20silence%20closes%22%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20SA%5B%22session%20A%3Cbr%2F%3Eevents%20at%202%2C%204%2C%208%22%5D%20~~~%20SB%5B%22session%20B%3Cbr%2F%3Eevents%20at%2015%2C%2019%22%5D%0A%20%20%20%20end%0A%20%20%20%20AX%5B%22event%20time%20%E2%80%94%200%20%C2%B7%C2%B7%C2%B7%205%20%C2%B7%C2%B7%C2%B7%2010%20%C2%B7%C2%B7%C2%B7%2015%20%C2%B7%C2%B7%C2%B7%2020%20min%22%5D%0A%20%20%20%20TW2%20~~~%20SW1%0A%20%20%20%20SW3%20~~~%20SA%0A%20%20%20%20SB%20~~~%20AX%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[s(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=r('<div class="info custom-block"><p class="custom-block-title">ℹ️ Session windows merge</p><p>A session window isn&#39;t known until the gap expires — a new event inside the gap extends it, and two sessions bridged by a late event <strong>merge into one</strong>. In Beam/Flink this is <code>MergingWindowFn</code>; it is the reason session analytics needs the merge machinery most simpler windows never touch.</p></div><h2 id="watermarks-the-completeness-heuristic" tabindex="-1">Watermarks: the completeness heuristic <a class="header-anchor" href="#watermarks-the-completeness-heuristic" aria-label="Permalink to &quot;Watermarks: the completeness heuristic&quot;">​</a></h2><p>A <strong>watermark</strong> is a claim: <em>&quot;we believe no more events with event time &lt; T will arrive.&quot;</em> Operators close event-time work (windows, joins, timers) when the watermark passes their end.</p>',3)),(o(),i(d,null,{default:t(()=>[a(n,{id:"mermaid-238",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Src%20as%20Source%20partition%20A%0A%20%20%20%20participant%20SrcB%20as%20Source%20partition%20B%0A%20%20%20%20participant%20Op%20as%20Window%20operator%0A%0A%20%20%20%20Note%20over%20Src%3A%20max%20event%20seen%2010%3A12%3Cbr%2F%3Ebound%205m%20%E2%86%92%20WM%20%3D%2010%3A07%0A%20%20%20%20Note%20over%20SrcB%3A%20max%20event%20seen%2010%3A09%3Cbr%2F%3Ebound%205m%20%E2%86%92%20WM%20%3D%2010%3A04%0A%20%20%20%20Src--%3E%3EOp%3A%20watermark%2010%3A07%0A%20%20%20%20SrcB--%3E%3EOp%3A%20watermark%2010%3A04%0A%20%20%20%20Note%20right%20of%20Op%3A%20operator%20WM%20%3D%20min(inputs)%3Cbr%2F%3E%3D%2010%3A04%0A%20%20%20%20Op-%3E%3EOp%3A%20close%20windows%20ending%20%E2%89%A4%2010%3A04%0A%20%20%20%20Note%20right%20of%20Op%3A%20window%20%5B10%3A00%2C10%3A10)%20still%20open%20%E2%80%94%3Cbr%2F%3Eslow%20partition%20gates%20the%20whole%20operator%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[s(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=r('<h3 id="how-watermarks-get-generated" tabindex="-1">How watermarks get generated <a class="header-anchor" href="#how-watermarks-get-generated" aria-label="Permalink to &quot;How watermarks get generated&quot;">​</a></h3><p>Two emission styles:</p><ul><li><strong>Periodic</strong> (the default, <code>WatermarkStrategy.forBoundedOutOfOrderness</code>) — the source emits <code>max_seen − bound</code> on a timer (<code>autoWatermarkInterval</code>, default 200 ms) regardless of record flow. Predictable, and it makes idle partitions visible.</li><li><strong>Punctuated</strong> — a watermark rides the stream after a marker record (a &quot;snapshot complete&quot; sentinel, an event boundary flag). Used when sources can <em>declare</em> completeness — CDC streams, file ingestion with explicit boundaries. Wrong markers = silently dropped data, so prefer periodic unless the source genuinely knows.</li></ul><p>Monotone inputs get a shortcut: <code>forMonotonousTimestamps()</code> emits <code>max_seen</code> as the watermark — correct when each partition&#39;s event times only increase (append-only logs, sequenced producers).</p><h3 id="the-critical-rules" tabindex="-1">The critical rules <a class="header-anchor" href="#the-critical-rules" aria-label="Permalink to &quot;The critical rules&quot;">​</a></h3><ul><li><strong><code>WM = max_event_time_seen − out_of_orderness_bound</code>.</strong> Bounded-out-of-orderness (<code>forBoundedOutOfOrderness(5 min)</code>) assumes no event is more than 5 minutes late vs the latest seen.</li><li><strong>Per-partition, then min.</strong> Each source partition keeps its own watermark; downstream operators take the <strong>minimum</strong> across inputs. One stalled partition — or one idle topic partition receiving no events — freezes the watermark and leaks state forever. <code>withIdleness</code> marks silent partitions idle so they stop gating.</li><li><strong>Watermark ≠ wall clock.</strong> It advances only when data with higher event times flows. No traffic → no watermark → no firing. (Idle-source detection is the fix.)</li><li><strong>Watermarks propagate downstream.</strong> The min rule applies at every operator — a slow upstream leg delays every window behind it.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ The watermark is a guess — size it like a risk decision</p><p>Too tight (30s) → real late events get dropped or side-output constantly, results are wrong-fast. Too loose (hours) → windows stay open, keyed state balloons, results are correct but late and expensive. The honest answer is a distribution: measure p99 lateness from your actual producers, set the bound there, and put the tail through allowed lateness or a side output rather than stretching the watermark.</p></div><h3 id="perfect-vs-heuristic-low-vs-high" tabindex="-1">Perfect vs heuristic, low vs high <a class="header-anchor" href="#perfect-vs-heuristic-low-vs-high" aria-label="Permalink to &quot;Perfect vs heuristic, low vs high&quot;">​</a></h3><p>Not all watermarks are the same object. Streaming Systems splits them two ways:</p><table tabindex="0"><thead><tr><th>Axis</th><th>Options</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Knowledge</strong></td><td><strong>Perfect</strong> — source <em>provably</em> knows completeness (bounded files, sequenced logs, CDC with boundaries)</td><td>Never wrong; rare outside replayable inputs</td></tr><tr><td></td><td><strong>Heuristic</strong> — estimate from observed arrivals (<code>max_seen − bound</code>)</td><td>Sometimes wrong; the wrongness is your late data</td></tr><tr><td><strong>Direction</strong></td><td><strong>Low watermark</strong> — tracks the <em>oldest</em> outstanding event (Beam, Flink, Dataflow)</td><td>Resilient to arbitrary skew: correctness degrades gracefully</td></tr><tr><td></td><td><strong>High watermark</strong> — tracks the <em>newest</em> event seen, then discards beyond a fixed lateness (Spark Structured Streaming)</td><td>Fast, but silently drops data whenever real skew exceeds your declared bound</td></tr></tbody></table><p>The low/high distinction matters when skew is unbounded. A low watermark follows the oldest event no matter how ugly the tail gets — a phone uploading a week of offline events delays results but doesn&#39;t corrupt them. A high watermark with a 10-minute bound simply discards that week. Same name, opposite failure mode.</p><h3 id="percentile-watermarks-and-the-correctness–latency-dial" tabindex="-1">Percentile watermarks and the correctness–latency dial <a class="header-anchor" href="#percentile-watermarks-and-the-correctness–latency-dial" aria-label="Permalink to &quot;Percentile watermarks and the correctness–latency dial&quot;">​</a></h3><p>A bound is a blunt instrument: one p99.99 straggler holds every window hostage. The refinement is a <strong>percentile watermark</strong> — emit the timestamp below which, say, 99.9% of observed event times fall, explicitly winnowing the slowest tail out of the calculation. The stragglers still get handled (allowed lateness, side output), they just stop gating everyone else.</p>',13)),(o(),i(d,null,{default:t(()=>[a(n,{id:"mermaid-366",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20dial%5B%22Correctness%20vs%20latency%20%E2%80%94%20one%20dial%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22bound%20tight%3Cbr%2F%3E(e.g.%20p50)%3Cbr%2F%3Eresults%20fast%2C%3Cbr%2F%3Emore%20late%20drops%22%5D%20---%20MID%5B%22bound%20~%20p99%3Cbr%2F%3Ethe%20usual%3Cbr%2F%3Esweet%20spot%22%5D%0A%20%20%20%20%20%20%20%20MID%20---%20B%5B%22bound%20loose%3Cbr%2F%3E(p99.999)%3Cbr%2F%3Ecorrect%2C%20late%2C%3Cbr%2F%3Estate-heavy%22%5D%0A%20%20%20%20end%0A%20%20%20%20A%20-.-%3E%7C%22side%20output%20carries%3Cbr%2F%3Ethe%20dropped%20tail%22%7C%20C%5B%22Total%20correctness%20%E2%89%88%20same%3B%3Cbr%2F%3Ewhat%20changes%20is%20WHERE%3Cbr%2F%3Ethe%20tail%20gets%20handled%22%5D%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[s(" Loading... ",-1)])]),_:1})),e[15]||(e[15]=r('<p>The subtle point the book makes: tightening the watermark doesn&#39;t necessarily lose data — it <em>relocates</em> it. Events the watermark passes become &quot;late&quot; and are recovered by allowed lateness or the side output. The bound chooses how much of your tail rides the fast path versus the correction path.</p><h3 id="where-event-time-skew-comes-from" tabindex="-1">Where event-time skew comes from <a class="header-anchor" href="#where-event-time-skew-comes-from" aria-label="Permalink to &quot;Where event-time skew comes from&quot;">​</a></h3><p>The bound you pick must cover the real sources of skew, which are physical, not statistical:</p><ul><li><strong>The data itself</strong> — offline devices batch-uploading hours of events (a plane landing and every phone leaving airplane mode at once), mobile clients buffering on poor connectivity. Unbounded, bursty, and the hardest to bound.</li><li><strong>Shared resources</strong> — network congestion, cross-region hops, CPU contention in multi-tenant environments, broker saturation during traffic spikes.</li><li><strong>Software causes</strong> — retries, backpressure, GC pauses, partition reassignment, a slow upstream operator queueing everything behind it.</li></ul><p>Skew is not a fixed property of the dataset — it&#39;s a varying function of everything between the event and your operator. That&#39;s why a bound measured on Tuesday&#39;s quiet traffic lies to you on Black Friday.</p><h3 id="propagation-and-idle-inputs" tabindex="-1">Propagation and idle inputs <a class="header-anchor" href="#propagation-and-idle-inputs" aria-label="Permalink to &quot;Propagation and idle inputs&quot;">​</a></h3>',6)),(o(),i(d,null,{default:t(()=>[a(n,{id:"mermaid-399",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20sources%5B%22Sources%20%E2%80%94%20per-partition%20watermarks%22%5D%0A%20%20%20%20%20%20%20%20P0%5B%22P0%3A%20WM%2010%3A12%22%5D%0A%20%20%20%20%20%20%20%20P1%5B%22P1%3A%20WM%2010%3A03%20%E2%86%90%20laggard%22%5D%0A%20%20%20%20%20%20%20%20P2%5B%22P2%3A%20idle%20(no%20events)%22%5D%0A%20%20%20%20end%0A%20%20%20%20OP1%5B%22keyBy%20%2B%20window%3Cbr%2F%3EWM%20%3D%20min(P0%2CP1)%20%3D%2010%3A03%3Cbr%2F%3Eidle%20P2%20ignored%20via%20withIdleness%22%5D%0A%20%20%20%20OP2%5B%22downstream%20operator%3Cbr%2F%3EWM%20%3D%20min(upstreams)%22%5D%0A%20%20%20%20P0%20--%3E%20OP1%0A%20%20%20%20P1%20--%3E%20OP1%0A%20%20%20%20P2%20-.-%3E%7C%22marked%20idle%20after%20timeout%22%7C%20OP1%0A%20%20%20%20OP1%20--%3E%20OP2%0A%20%20%20%20OP2%20--%3E%20S%5B%22Sink%20sees%20WM%2010%3A03%20%E2%80%94%3Cbr%2F%3Eevery%20downstream%20window%3Cbr%2F%3Einherits%20the%20laggard%22%5D%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[s(" Loading... ",-1)])]),_:1})),e[16]||(e[16]=r('<p>Dataflow-class engines add refinements worth knowing exist: <strong>heuristic/gradient watermarks</strong> (a confidence-weighted estimate instead of a hard bound, so a single straggler doesn&#39;t stall the pipeline) and <strong>heartbeat watermarks</strong> (sources emit watermark progress even without data, fixing the idle-partition stall without idleness detection). The semantics are the same — these are better estimators of the same bet.</p><h2 id="firing-triggers-allowed-lateness-side-outputs" tabindex="-1">Firing: triggers, allowed lateness, side outputs <a class="header-anchor" href="#firing-triggers-allowed-lateness-side-outputs" aria-label="Permalink to &quot;Firing: triggers, allowed lateness, side outputs&quot;">​</a></h2><p>Three independent levers decide <em>when</em> a window produces output and <em>how long</em> it can be revised:</p><ul><li><strong>Trigger</strong> — the rule that fires a pane: default is &quot;watermark passes window end&quot;; <code>EarlyFiring</code>/<code>processingTime</code> triggers emit partial results on a cadence (&quot;every 1 min, emit whatever&#39;s accumulated&quot;); <code>AfterCount</code>/<code>AfterElement</code> for record-count fires.</li><li><strong>Allowed lateness</strong> — how long after the watermark crosses window-end the window keeps its state and can <em>refire</em> on late arrivals. <code>allowedLateness(3 min)</code> = revisions accepted until <code>WM ≥ window_end + 3 min</code>.</li><li><strong>Side output / late data tag</strong> — events arriving after allowed lateness (or outside the watermark entirely) get routed to a side channel: a DLQ, a correction table, a reprocessing topic. Never silently drop them — a late event is a fact, not garbage.</li></ul>',4)),(o(),i(d,null,{default:t(()=>[a(n,{id:"mermaid-426",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20E%5B%22Event%20arrives%2C%20event_time%20%3D%2010%3A08%22%5D%20--%3E%20Q1%7B%22WM%20%3C%20window_end%3F%3Cbr%2F%3E(WM%20%3C%2010%3A10)%22%7D%0A%20%20%20%20Q1%20--%3E%7C%22yes%20%E2%80%94%20on%20time%22%7C%20ACC%5B%22Accumulate%20into%20window%20state%22%5D%0A%20%20%20%20Q1%20--%3E%7C%22no%20%E2%80%94%20but%20WM%20%3C%2010%3A10%20%2B%203m%20lateness%22%7C%20REFIRE%5B%22Add%20to%20window%2C%3Cbr%2F%3Erefire%20updated%20pane%22%5D%0A%20%20%20%20Q1%20--%3E%7C%22no%20%E2%80%94%20window%20purged%22%7C%20SO%5B%22Side%20output%3A%3Cbr%2F%3Ecorrections%20topic%22%5D%0A%20%20%20%20ACC%20--%3E%20FIRE%5B%22WM%20crosses%2010%3A10%20%E2%86%92%3Cbr%2F%3Ewindow%20emits%20result%22%5D%0A%20%20%20%20REFIRE%20--%3E%20RERESULT%5B%22Downstream%20sees%20v2%2C%20v3%E2%80%A6%3Cbr%2F%3Eof%20the%20same%20window%22%5D%0A"})]),fallback:t(()=>[...e[7]||(e[7]=[s(" Loading... ",-1)])]),_:1})),e[17]||(e[17]=r('<h3 id="accumulation-modes-how-panes-relate" tabindex="-1">Accumulation modes: how panes relate <a class="header-anchor" href="#accumulation-modes-how-panes-relate" aria-label="Permalink to &quot;Accumulation modes: how panes relate&quot;">​</a></h3><p>Once a window can fire more than once, a second question appears: is each emitted pane a <em>delta</em>, a <em>new total</em>, or a <em>correction</em>? Beam&#39;s three accumulation modes — the &quot;How&quot; of the four questions — answer it differently. Same window, same two firings (inputs <code>3</code> then <code>8, 1</code>; true sum = 12):</p><table tabindex="0"><thead><tr><th>Pane</th><th>Discarding</th><th>Accumulating</th><th>Accumulating + retracting</th></tr></thead><tbody><tr><td>Pane 1 (inputs: 3)</td><td>3</td><td>3</td><td>3</td></tr><tr><td>Pane 2 (inputs: 8, 1)</td><td>9</td><td>12</td><td>12, −3 <em>(retract prior)</em></td></tr><tr><td><strong>Final pane value</strong></td><td>9</td><td>12</td><td>12</td></tr><tr><td><strong>Sum of all panes</strong></td><td>12</td><td>15 ❌</td><td>12</td></tr></tbody></table><ul><li><strong>Discarding</strong> throws state away after each firing — every pane is an independent delta. Correct only if the <em>consumer</em> sums panes itself (delta-feed into an accumulator). If the consumer takes the last value, you under-report.</li><li><strong>Accumulating</strong> keeps state — each pane is a complete running result. Perfect for sinks that overwrite in place (key-value store keyed on window). If the consumer <em>sums</em> panes, you double-count (15 above).</li><li><strong>Accumulating + retracting</strong> emits the new total <em>plus</em> an explicit retraction of the previous pane. Both &quot;last value&quot; and &quot;sum of everything&quot; yield 12 — the only mode that&#39;s safe for a naive appending consumer. It&#39;s also the only sane choice when windows <strong>merge</strong> (sessions): a merged result replaces several old windows, and only explicit retractions tell downstream which.</li></ul><p>Cost increases down the list: discarding stores nothing between firings, retracting must remember the last emitted pane per window <em>and</em> emit two records per firing. Pick the cheapest mode your sink&#39;s semantics tolerate.</p><div class="tip custom-block"><p class="custom-block-title">💡 Match the mode to the sink</p><p>KV store / upsert warehouse → accumulating. Delta-hungry downstream accumulator → discarding. Appending log, replayed topics, merging sessions → retracting. The bug in every case is the same shape: the consumer&#39;s aggregation assumption and the producer&#39;s accumulation mode disagree, and both sides look locally correct.</p></div><h3 id="choosing-a-late-data-strategy" tabindex="-1">Choosing a late-data strategy <a class="header-anchor" href="#choosing-a-late-data-strategy" aria-label="Permalink to &quot;Choosing a late-data strategy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Strategy</th><th>What you accept</th><th>Cost</th><th>Fits</th></tr></thead><tbody><tr><td>Tight WM + side output</td><td>On-time result fast; stragglers go to corrections</td><td>Complexity: a second write path consumers must handle</td><td>Dashboards with SLOs, audit-required pipelines</td></tr><tr><td>Generous allowed lateness</td><td>Refires produce revised results</td><td>State lives longer; downstream must handle updates (upserts)</td><td>Warehouse sinks that can upsert; most production analytics</td></tr><tr><td>Loose watermark</td><td>Almost everything is &quot;on time&quot;</td><td>Slowest straggler gates all output; state balloons</td><td>Low-volume feeds with wild latency</td></tr><tr><td>Processing time</td><td>No lateness concept</td><td>Non-reproducible; replay gives different answers</td><td>Monitoring/alerting where &quot;now&quot; is the semantic</td></tr><tr><td>Drop late silently</td><td>Simplicity</td><td>Silent wrongness — the worst option</td><td>Never for anything reported upward</td></tr></tbody></table><h3 id="trigger-recipes-that-show-up-in-production" tabindex="-1">Trigger recipes that show up in production <a class="header-anchor" href="#trigger-recipes-that-show-up-in-production" aria-label="Permalink to &quot;Trigger recipes that show up in production&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Goal</th><th>Recipe</th></tr></thead><tbody><tr><td>&quot;Final result per window, revised for late data&quot;</td><td>Default event-time trigger + <code>allowedLateness</code></td></tr><tr><td>&quot;Live dashboard + final result&quot;</td><td><code>AfterWatermark.pastEndOfWindow()</code> with <code>withEarlyFirings</code> on a processing-time cadence — early partials every minute, then the on-time pane</td></tr><tr><td>&quot;Alert on bursts&quot;</td><td>Global window + <code>AfterCount(n)</code> or processing-time trigger — no waiting for event time</td></tr><tr><td>&quot;Exactly-once-ish accounting&quot;</td><td>On-time pane only, discarding mode; treat refires as updates, not appends</td></tr></tbody></table><h2 id="checkpoints-state-and-the-real-cost-of-lateness" tabindex="-1">Checkpoints, state, and the real cost of lateness <a class="header-anchor" href="#checkpoints-state-and-the-real-cost-of-lateness" aria-label="Permalink to &quot;Checkpoints, state, and the real cost of lateness&quot;">​</a></h2><p>Window state lives in the state backend until the window is <em>purged</em> — window end + allowed lateness. Two coupled dials:</p><ul><li><strong>Longer allowed lateness</strong> → more keys&#39; windows open at once → bigger keyed state, longer RocksDB snapshots, slower recovery.</li><li><strong>Shorter checkpoint interval</strong> → faster recovery (less reprocessing after failure) but more snapshot overhead; with incremental RocksDB, frequent small checkpoints are usually cheaper than rare large ones.</li><li><strong>Per-key state compounds</strong>: a session window with allowed lateness × millions of keys × a fat accumulator is how a job quietly grows from 2 GB to 200 GB.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Rule of thumb</p><p>Set <code>state.ttl</code> and allowed lateness together — they are the same decision expressed twice. A window that can refire for 3 minutes should not keep state for a week; a TTL shorter than your lateness horizon silently drops the late data you said you&#39;d accept.</p></div><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p><strong>Spec:</strong> 10-minute tumbling windows over clickstream, watermark = 5-minute bounded out-of-orderness, allowed lateness = 3 minutes. Window W = <code>[10:00, 10:10)</code>.</p><table tabindex="0"><thead><tr><th>Arrival (proc. time)</th><th>Event time</th><th>WM after event</th><th>What happens</th></tr></thead><tbody><tr><td>10:00:02</td><td>10:00</td><td>09:55</td><td>Accumulates in W</td></tr><tr><td>10:05:00</td><td>10:05</td><td>10:00</td><td>Accumulates</td></tr><tr><td>10:11:00</td><td>10:11</td><td>10:06</td><td>Next window [10:10,10:20); W still open</td></tr><tr><td>10:16:00</td><td>10:16</td><td><strong>10:11</strong></td><td><strong>WM crosses 10:10 → W fires v1</strong></td></tr><tr><td>10:18:00</td><td>10:07 (late, 9 min behind tip)</td><td>10:11</td><td>Within lateness (WM &lt; 10:10+3=10:13): <strong>W refires v2</strong></td></tr><tr><td>10:20:00</td><td>10:19</td><td>10:14</td><td>WM ≥ 10:13 → <strong>W&#39;s state purged</strong></td></tr><tr><td>10:25:00</td><td>10:06</td><td>10:20</td><td>Past purge → <strong>side output</strong></td></tr></tbody></table><p>Read it twice: the window emitted <strong>three</strong> artifacts — v1 at fire, v2 at refire, and a side-output record — and any consumer that writes results as inserts (not upserts keyed on window) just double-counted.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Refires are updates, not new rows</p><p>If the sink appends, allowed-lateness refires will silently inflate your aggregates — the same failure class as join fan-out, one level down. Sinks that take streaming window output must be upsert-capable or versioned on (key, window_end).</p></div><h3 id="see-it-move" tabindex="-1">See it move <a class="header-anchor" href="#see-it-move" aria-label="Permalink to &quot;See it move&quot;">​</a></h3>',20)),a(u),e[18]||(e[18]=r('<p>Step through 10 arrivals (slider jumps to any point). Each event sits at its <strong>event time</strong> on the top row; the dot on the bottom row is when it actually arrived — the dashed skew line between them is the lateness. The red watermark is <code>max event time seen − 3 min</code>.</p><ul><li><strong>Step arrival</strong> — one event at a time. Watch <code>[10:00,10:10)</code> fire the moment WM crosses 10:10, then <em>refire</em> when the 10:05 event shows up at processing-time 10:15 — still inside the 5-minute lateness horizon.</li><li><strong>allowed lateness</strong> toggle — on, late events inside <code>window_end + 5m</code> refire the window; off, everything after the first firing goes straight to the side output, and the 10:02 straggler always lands there once state is purged.</li><li><strong>retractions</strong> toggle — switches refires from bare updated panes to retraction + new pane pairs (accumulating-and-retracting mode): the downstream contract for consumers that can&#39;t overwrite.</li></ul><p>Two events are planted late on purpose: <code>10:05 arriving 10:15</code> (within lateness → refire) and <code>10:02 arriving 10:20</code> (past purge → side output). They&#39;re the worked example above, animated.</p><h2 id="design-checklist-for-windowed-pipelines" tabindex="-1">Design checklist for windowed pipelines <a class="header-anchor" href="#design-checklist-for-windowed-pipelines" aria-label="Permalink to &quot;Design checklist for windowed pipelines&quot;">​</a></h2><ul><li><strong>Pick the clock deliberately.</strong> Event time for anything reported; processing time only for &quot;right now&quot; alerting. If you can&#39;t articulate why, it&#39;s event time.</li><li><strong>Measure lateness before choosing a bound.</strong> Look at your producers&#39; actual p50/p99/p999 arrival skew, then set the watermark at the tail you&#39;re willing to treat as on-time.</li><li><strong>Bound the revision window.</strong> Allowed lateness is a state-budget decision as much as a correctness one — set it, pair it with <code>state.ttl</code>, and write down why.</li><li><strong>Route the tail somewhere.</strong> Side output to a corrections/DLQ path; a late event that vanishes is a fact you chose to lose.</li><li><strong>Make the sink upsert-aware.</strong> Windows refire; appending sinks double-count. Key results on (entity, window_end) or accept eventual-consistency corrections.</li><li><strong>Kill idle partitions&#39; veto.</strong> <code>withIdleness</code> on sources; heartbeat watermarks if your runner supports them.</li><li><strong>Watch watermark lag, not just consumer lag.</strong> <code>currentOutputWatermark</code> behind event time is the leading indicator that windows are stalling — before lag metrics notice.</li></ul><details class="details custom-block"><summary>Stream-stream joins are windows in disguise</summary><p>Joining two unbounded streams has no natural end either — you join on a key <em>and</em> a time interval (event-time window join, or interval join in Flink). Both sides buffer state until the watermark rules out more matches, which means join state size is governed by the join window plus watermark skew, and a slow input on either side holds both sides&#39; state open. Interval joins (<code>a.time BETWEEN b.time - 5m AND b.time + 5m</code>) are the practical tool: explicit bounds, explicit state lifetime. Unbounded &quot;temporal&quot; joins that never expire are how jobs end up with 500 GB of state nobody remembers creating.</p></details><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',7)),a(c,{questions:[{q:"Why prefer event time over processing time for analytics?",options:["It is faster to compute","Results are reproducible — replays and lag do not change which window an event lands in","It needs no watermarks","It uses less state"],correct:1,explain:"Event time ties the result to when things happened, not when the pipeline happened to read them. Processing-time windows give different answers on every replay or lag spike."},{q:"A two-input operator receives watermark 10:07 on partition A and 10:04 on partition B. Its effective watermark?",options:["10:07 — the max","10:05:30 — the average","10:04 — the min; the slowest input gates the operator","Whichever arrived last"],correct:2,explain:"Watermark = min(inputs). One lagging or idle partition stalls every downstream window — which is why idle-source detection exists."},{q:"Watermark bound is 5m. Event at event-time 10:16 arrives. A window ending 10:10…",options:["Cannot fire — event is in the future","Fires only after 5 more minutes of wall time","Already closed at 10:10","Fires now — the watermark advanced to 10:11, past the window end"],correct:3,explain:"WM = max_seen - bound = 10:16 - 5m = 10:11 > 10:10. The watermark is driven by event times in the stream, not wall clock."},{q:"Window fires at WM crossing, then a late event arrives within allowed lateness. The window…",options:["Blocks the watermark","Is dropped — too late","Refires an updated pane; the sink must handle revisions (upsert/version)","Goes to the side output immediately"],correct:2,explain:"Allowed lateness = the window keeps state and can emit revised results. Only after WM passes window_end + lateness is state purged and do further laggards hit the side output."},{q:"A partition in your Kafka source has had no traffic for an hour. Window output stalls because…",options:["Kafka stopped delivering","The idle partition holds the min watermark back — fix with idleness detection","Checkpoints are too frequent","Session windows never close"],correct:1,explain:"No events means no watermark progress on that partition, and min() gates the operator. withIdleness (or heartbeat watermarks) lets silent inputs be ignored."},{q:"Biggest lever on streaming job state size for windowed aggregation?",options:["Bigger checkpoint interval","More partitions","Watermark bound + allowed lateness — how long each window stays open before purge","More TaskManager slots"],correct:2,explain:"State accumulates per open window per key. The completeness knobs decide the retention horizon; checkpoints and parallelism just move the bytes around."}]}),a(c,{questions:[{q:"In the What/Where/When/How model, which question do watermarks + triggers answer?",options:["How refinements relate","Where in event time results are computed","What results are calculated","When in processing time results are materialized"],correct:3,explain:"When = triggers and watermarks: the bet on input completeness that decides when a pane is emitted. Where = windowing, How = accumulation mode."},{q:"A window fires pane 1 = 3, then pane 2 = 9 under DISCARDING mode (true sum 12). A consumer that keeps the last pane reports…",options:["3 — the first pane wins","12 — panes always carry the running total","9 — discarding emits deltas; last-pane consumers under-report","15 — panes sum together"],correct:2,explain:"Discarding makes each pane an independent delta: only a consumer that sums panes sees 12. Accumulating mode would report 12 on the last pane but 15 if summed."},{q:"Spark Structured Streaming uses a high watermark with a fixed lateness bound vs Flink-style low watermark. A phone uploads a week of offline events — what happens?",options:["Both drop the data","High WM handles it gracefully","High WM: events past the bound are discarded; low WM: results stall but stay correct","Both systems hold state a week"],correct:2,explain:"Low watermarks track the oldest outstanding event and degrade to latency under unbounded skew; high watermarks assume skew fits your declared bound and silently drop anything beyond it."}]}),e[19]||(e[19]=r('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://www.oreilly.com/radar/the-world-beyond-batch-streaming-101" target="_blank" rel="noreferrer">Streaming 101: The world beyond batch — Tyler Akidau (O&#39;Reilly Radar)</a></li><li><a href="https://www.oreilly.com/radar/the-world-beyond-batch-streaming-102/" target="_blank" rel="noreferrer">Streaming 102: The world beyond batch — Tyler Akidau (O&#39;Reilly Radar)</a></li><li><a href="https://beam.apache.org/documentation/programming-guide/" target="_blank" rel="noreferrer">Apache Beam Programming Guide — watermarks, triggers, windowing</a></li><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/docs/concepts/time/" target="_blank" rel="noreferrer">Flink docs — timely stream processing / event time</a></li><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/docs/dev/datastream/event-time/generating_watermarks/" target="_blank" rel="noreferrer">Flink docs — generating watermarks</a></li><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/docs/dev/datastream/operators/windows/" target="_blank" rel="noreferrer">Flink docs — windows</a></li><li><a href="https://www.oreilly.com/library/view/streaming-systems/9781491983867/" target="_blank" rel="noreferrer">Streaming Systems — Akidau, Chernyak, Lax (O&#39;Reilly)</a></li><li><a href="https://spark.apache.org/docs/latest/structured-streaming-programming-guide.html#handling-late-data-and-watermarking" target="_blank" rel="noreferrer">Spark Structured Streaming — watermarking</a></li></ul>',2))])}const C=m(g,[["render",w]]);export{E as __pageData,C as default};
